import {documentToReactComponents} from '@contentful/rich-text-react-renderer'
import {BLOCKS} from '@contentful/rich-text-types'
import type {Document} from '@contentful/rich-text-types'
import {OrderedList} from '@primer/react-brand'
import {StaticSignupStep} from './StaticSignupStep'

import styles from './StaticSignupsSteps.module.css'

interface StaticSignupStepsProps {
  content: Document
}

export const StaticSignupSteps = ({content}: StaticSignupStepsProps): React.ReactNode => {
  return documentToReactComponents(content, {
    renderNode: {
      [BLOCKS.OL_LIST]: node => {
        return (
          <OrderedList className={styles.listStyleContainer} data-testid={'static-signup-steps'}>
            {node.content.map((itemNode, idx) => {
              const bulletText = (itemNode as {content: Array<{content: Array<{value: string}>}>}).content
                .map((paragraph: {content: Array<{value: string}>}) =>
                  paragraph.content.map((text: {value: string}) => text.value).join(''),
                )
                .join('')
              return (
                <OrderedList.Item key={bulletText} className={styles.listStyle} data-testid={`static-step-${idx + 1}`}>
                  <StaticSignupStep stepIndex={idx} bulletText={bulletText} />
                </OrderedList.Item>
              )
            })}
          </OrderedList>
        )
      },
    },
  })
}

try{ StaticSignupSteps.displayName ||= 'StaticSignupSteps' } catch {}